mapper.select:
SELECT * FROM integration_outbox
WHERE provider = #{provider}
  AND status IN ('PENDING', 'FAILED_RETRYABLE')
  AND (next_retry_at IS NULL OR next_retry_at <= NOW(3))
ORDER BY id ASC LIMIT #{limit}

SELECT * FROM integration_outbox
WHERE provider != #{provider}
  AND status IN ('PENDING', 'FAILED_RETRYABLE')
  AND (next_retry_at IS NULL OR next_retry_at <= NOW(3))
ORDER BY id ASC LIMIT #{limit}
